if !(IsFeatureImplemented(FEAT_S1POE2) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif EffectivelyAtEL0InHost() || EffectivelyAtEL0NotInHost() then
    Undefined();
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && IsFeatureImplemented(FEAT_FGT2) && (!HaveEL(EL3) || SCR_EL3().FGTEn2 == '1') && HFGITR2_EL2().PLBIVMALLE1 == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EffectiveHCR_EL2_NVx() == 'xx1' && !(IsFeatureImplemented(FEAT_NV3) && EffectiveHCRX_EL2_NVTGE() == '1' && NVHCR_EL2().TGE == '1') then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        AArch64_PLBI_VMALL(SecurityStateAtEL(EL1), Regime_EL10, VMID(), Broadcast_NSH, PLBI_AllAttr, X{64}(t));
    end;
elsif PSTATE.EL == EL2 then
    AArch64_PLBI_VMALL(SecurityStateAtEL(EL1), Regime_EL10, VMID(), Broadcast_NSH, PLBI_AllAttr, X{64}(t));
elsif PSTATE.EL == EL3 then
    if IsFeatureImplemented(FEAT_S1POE2) && FGDTState.E0 == '1' then
        AArch64_SystemAccessTrap(EL3, 0x18);
    else
        if IsFeatureImplemented(FEAT_RME) && !ValidSecurityStateAtEL(EL1) then
            return;
        else
            AArch64_PLBI_VMALL(SecurityStateAtEL(EL1), Regime_EL10, VMID(), Broadcast_NSH, PLBI_AllAttr, X{64}(t));
        end;
    end;
end;

if !(IsFeatureImplemented(FEAT_S1POE2) && IsFeatureImplemented(FEAT_AA64)) then
    Undefined();
elsif !IsFeatureImplemented(FEAT_XS) then
    Undefined();
elsif EffectivelyAtEL0InHost() || EffectivelyAtEL0NotInHost() then
    Undefined();
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && IsFeatureImplemented(FEAT_FGT2) && (!HaveEL(EL3) || SCR_EL3().FGTEn2 == '1') && HFGITR2_EL2().PLBIVMALLE1 == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EffectiveHCR_EL2_NVx() == 'xx1' && !(IsFeatureImplemented(FEAT_NV3) && EffectiveHCRX_EL2_NVTGE() == '1' && NVHCR_EL2().TGE == '1') then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        AArch64_PLBI_VMALL(SecurityStateAtEL(EL1), Regime_EL10, VMID(), Broadcast_NSH, PLBI_ExcludeXS, X{64}(t));
    end;
elsif PSTATE.EL == EL2 then
    AArch64_PLBI_VMALL(SecurityStateAtEL(EL1), Regime_EL10, VMID(), Broadcast_NSH, PLBI_ExcludeXS, X{64}(t));
elsif PSTATE.EL == EL3 then
    if IsFeatureImplemented(FEAT_S1POE2) && FGDTState.E0 == '1' then
        AArch64_SystemAccessTrap(EL3, 0x18);
    else
        if IsFeatureImplemented(FEAT_RME) && !ValidSecurityStateAtEL(EL1) then
            return;
        else
            AArch64_PLBI_VMALL(SecurityStateAtEL(EL1), Regime_EL10, VMID(), Broadcast_NSH, PLBI_ExcludeXS, X{64}(t));
        end;
    end;
end;
